mkdir -p /app/output && cat > /app/output/styles.css << 'EOF'
@import url('https://fonts.googleapis.com/css2?family=Playfair+Display:wght@500;600;700;800&family=Inter:wght@400;500;600;700&display=swap');

:root {
  --bg: #f5f2ed;
  --text: #1a1a1a;
  --muted: #5f5a54;
  --line: #d8d1c9;
  --accent-1: #b88b72;
  --accent-2: #a6b39e;
  --accent-3: #d3bb96;
  --max-width: 1280px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { width: 100%; }
body {
  font-family: 'Inter', sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.6;
}

a { color: inherit; text-decoration: none; }

.site-wrap { min-height: 100vh; }
.container {
  width: min(var(--max-width), 92vw);
  margin: 0 auto;
}

.site-header {
  padding: 2rem 0;
  position: sticky;
  top: 0;
  background: color-mix(in srgb, var(--bg) 90%, transparent);
  backdrop-filter: blur(6px);
  z-index: 20;
}
.header-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
}
.brand {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.5rem, 2vw, 1.85rem);
  font-weight: 700;
  letter-spacing: 0.01em;
}
.nav-desktop { display: flex; gap: 2rem; }
.nav-desktop a {
  font-size: 0.95rem;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}
.nav-desktop a:hover { opacity: 0.65; }

.menu-btn {
  display: none;
  width: 44px;
  height: 44px;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--text);
  align-items: center;
  justify-content: center;
  cursor: pointer;
}
.menu-btn span,
.menu-btn span::before,
.menu-btn span::after {
  display: block;
  width: 18px;
  height: 2px;
  background: var(--text);
  position: relative;
  transition: transform .25s ease, opacity .2s ease;
}
.menu-btn span::before,
.menu-btn span::after {
  content: '';
  position: absolute;
  left: 0;
}
.menu-btn span::before { top: -6px; }
.menu-btn span::after { top: 6px; }
.menu-btn.open span { background: transparent; }
.menu-btn.open span::before { transform: translateY(6px) rotate(45deg); }
.menu-btn.open span::after { transform: translateY(-6px) rotate(-45deg); }

.mobile-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg);
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .28s ease;
  z-index: 19;
}
.mobile-overlay.open {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.mobile-nav {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  text-align: center;
}
.mobile-nav a {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 7vw, 3.6rem);
  line-height: 1.05;
}

.hero { padding: 8vh 0 12vh; }
.kicker {
  text-transform: uppercase;
  letter-spacing: .14em;
  font-size: .74rem;
  color: var(--muted);
  margin-bottom: 1.25rem;
}
.display {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2.6rem, 8vw, 7.4rem);
  line-height: .95;
  font-weight: 700;
  max-width: 14ch;
}
.lead {
  margin-top: 2rem;
  max-width: 56ch;
  font-size: clamp(1.05rem, 1.5vw, 1.25rem);
  color: #3f3a35;
}

.media-grid {
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 1rem;
  margin: 8vh 0 10vh;
}
.block {
  border-radius: 4px;
  min-height: 240px;
}
.block.lg { min-height: 440px; background: var(--accent-1); }
.block.md { min-height: 210px; background: var(--accent-2); }
.block.sm { min-height: 210px; background: var(--accent-3); }
.stack { display: grid; gap: 1rem; }

.section { padding: 10vh 0; border-top: 1px solid var(--line); }
.section-title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2rem, 5vw, 4.2rem);
  line-height: 1.02;
  margin-bottom: 1.25rem;
}

.marquee-wrap { padding: 1rem 0 .25rem; }
.marquee-row {
  overflow: hidden;
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
  margin-bottom: -1px;
}
.track {
  display: flex;
  width: max-content;
  gap: 2.6rem;
  padding: 1rem 0;
  will-change: transform;
  animation: marquee-left 28s linear infinite;
}
.row-right .track { animation-name: marquee-right; }
.brand-pill {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.1rem, 2.3vw, 1.8rem);
  white-space: nowrap;
}
@keyframes marquee-left {
  from { transform: translateX(0); }
  to { transform: translateX(-50%); }
}
@keyframes marquee-right {
  from { transform: translateX(-50%); }
  to { transform: translateX(0); }
}

.copy { max-width: 66ch; font-size: 1.07rem; color: #3f3a35; }
.copy p + p { margin-top: 1.1rem; }

.editorial {
  max-width: 76ch;
  margin: 0 auto;
  padding: 6vh 0 12vh;
}
.editorial .title {
  font-family: 'Playfair Display', serif;
  font-size: clamp(2.2rem, 7vw, 5.8rem);
  line-height: .95;
  margin-bottom: 2rem;
}
.editorial .meta {
  text-transform: uppercase;
  letter-spacing: .12em;
  font-size: .72rem;
  color: var(--muted);
  margin-bottom: 2rem;
}
.editorial p {
  font-size: clamp(1.06rem, 1.35vw, 1.22rem);
  line-height: 1.95;
  color: #37332f;
}
.editorial p + p { margin-top: 1.5rem; }

.services-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 2rem;
  margin-top: 2rem;
}
.card h3 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.6rem, 3.1vw, 2.6rem);
  margin-bottom: .7rem;
}
.card p { color: #403b36; }

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0,1fr));
  gap: 2rem 2.5rem;
}
.client-item h3 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(1.45rem, 2.3vw, 2rem);
  margin-bottom: .35rem;
}
.client-item p { color: #4a443d; }

.contact-hero {
  min-height: calc(100vh - 180px);
  display: grid;
  align-content: center;
  gap: 2rem;
}
.contact-hero h1 {
  font-family: 'Playfair Display', serif;
  font-size: clamp(4rem, 20vw, 17rem);
  line-height: .82;
  letter-spacing: -0.02em;
}
.contact-links a {
  display: block;
  width: fit-content;
  font-size: clamp(1.2rem, 2.2vw, 2rem);
  margin-bottom: .5rem;
}

@media (max-width: 960px) {
  .nav-desktop { display: none; }
  .menu-btn { display: inline-flex; }
  .media-grid { grid-template-columns: 1fr; }
  .block.lg { min-height: 320px; }
  .services-grid, .clients-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 680px) {
  .site-header { padding: 1.2rem 0; }
  .hero { padding-top: 5vh; }
  .services-grid, .clients-grid { grid-template-columns: 1fr; }
}
EOF

cat > /app/output/script.js << 'EOF'
(function () {
  const menuButton = document.querySelector('[data-menu-btn]');
  const overlay = document.querySelector('[data-mobile-overlay]');

  if (menuButton && overlay) {
    menuButton.addEventListener('click', function () {
      const isOpen = menuButton.classList.toggle('open');
      overlay.classList.toggle('open', isOpen);
      menuButton.setAttribute('aria-expanded', String(isOpen));
      document.body.style.overflow = isOpen ? 'hidden' : '';
    });

    overlay.querySelectorAll('a').forEach(function (link) {
      link.addEventListener('click', function () {
        menuButton.classList.remove('open');
        overlay.classList.remove('open');
        menuButton.setAttribute('aria-expanded', 'false');
        document.body.style.overflow = '';
      });
    });
  }
})();
EOF

